<?php require_once __DIR__.'/_init.php'; PA_KasirBridge::ensureTables($pdo); if($_SERVER['REQUEST_METHOD']!=='POST'){header('Location:index.php');exit;} pa_verify_csrf(); $jobId=(int)($_POST['job_id']??0); $pageId=(int)($_POST['page_id']??0); $cat=(string)($_POST['category']??''); if(!array_key_exists($cat,pa_setting('categories',[]))){ pa_flash('error','Kategori tidak valid.'); header('Location: job.php?id='.$jobId); exit; }
$st=$pdo->prepare('SELECT pp.*, p.colored_pixel_percentage FROM print_jobs j JOIN price_profiles pp ON pp.id=j.price_profile_id JOIN print_job_pages p ON p.print_job_id=j.id WHERE j.id=? AND p.id=?'); $st->execute([$jobId,$pageId]); $profile=$st->fetch(PDO::FETCH_ASSOC); if(!$profile){http_response_code(404);exit('Halaman tidak ditemukan');}
$pricing=new PA_PriceCalculator(); $unit=$pricing->unitPrice($profile,$cat); $pdo->prepare('UPDATE print_job_pages SET final_category=?, overridden=1, unit_price=? WHERE id=? AND print_job_id=?')->execute([$cat,$unit,$pageId,$jobId]); PA_AnalyzerSettings::learnFromCorrection($pdo,(float)$profile['colored_pixel_percentage'],$cat); $pricing->refreshJob($pdo,$jobId); pa_flash('success','Kategori halaman disimpan dan setting deteksi otomatis belajar.'); header('Location: job.php?id='.$jobId); exit;